import java.util.ArrayList;
import java.util.List;
import java.util.Map;

class ProteinTranslator {

    private static final Map<String, String> CODON_MAP = Map.of(
        "AUG", "Methionine",
        "UUU", "Phenylalanine",
        "UUC", "Phenylalanine",
        "UUA", "Leucine",
        "UUG", "Leucine",
        "UCU", "Serine",
        "UCC", "Serine",
        "UCA", "Serine",
        "UCG", "Serine",
        "UAU", "Tyrosine",
        "UAC", "Tyrosine",
        "UGU", "Cysteine",
        "UGC", "Cysteine",
        "UGG", "Tryptophan",
        "UAA", "STOP",
        "UAG", "STOP",
        "UGA", "STOP"
    );

    List<String> translate(String rnaSequence) {
        List<String> proteins = new ArrayList<>();

        if (rnaSequence == null || rnaSequence.isEmpty()) {
            return proteins;
        }

        for (int i = 0; i < rnaSequence.length(); i += 3) {
            if (i + 3 > rnaSequence.length()) {
                throw new IllegalArgumentException("Invalid codon");
            }

            String codon = rnaSequence.substring(i, i + 3);
            String protein = CODON_MAP.get(codon);

            if (protein == null) {
                throw new IllegalArgumentException("Invalid codon");
            }

            if ("STOP".equals(protein)) {
                break;
            }

            proteins.add(protein);
        }

        return proteins;
    }
}

